?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shopkeeper Packages · ShahkotPK</title><style>body{margin:0;background:#f3f7fc;color:#10213a;font-family:system-ui}.wrap{max-width:1100px;margin:auto;padding:30px}.hero{background:linear-gradient(135deg,#071b37,#2853c7);color:#fff;padding:30px;border-radius:26px}.hero h1{font-size:42px;margin:5px 0}.notice{padding:13px;border-radius:14px;margin:14px 0}.ok{background:#e6f9ef}.bad{background:#ffecec}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card{background:#fff;border:1px solid #dce5f0;border-radius:20px;padding:20px;box-shadow:0 12px 30px #18335a10}.card.current{border:2px solid #2863ec}.price{font-size:27px;font-weight:900}.btn{border:0;background:#2062e7;color:#fff;font-weight:800;padding:11px 15px;border-radius:12px;cursor:pointer}.card textarea{width:100%;box-sizing:border-box;margin:10px 0;padding:10px;border-radius:10px;border:1px solid #d5dfec}.history{background:#fff;padding:20px;border-radius:20px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #e5ebf2;text-align:left}@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.grid{grid-template-columns:1fr}.hero h1{font-size:30px}}</style></head><body><main class="wrap"><section class="hero"><small>SHAHKOTPK SHOPKEEPER ACCESS</small><h1>Choose your business package</h1><p>Your package controls business tools and limits. Admin-only modules are never included.</p><p><b>Current:</b> <?=sk1300_h($current['name']??'Starter Shop')?></p></section><?php if($msg):?><div class="notice ok"><?=sk1300_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1300_h($err)?></div><?php endif;?><section class="grid"><?php foreach($packs as $p):?><article class="card <?=(int)($current['id']??0)===(int)$p['id']?'current':''?>"><h2><?=sk1300_h($p['name'])?></h2><div class="price">PKR <?=number_format((float)$p['price'],0)?></div><small><?=sk1300_h($p['billing_cycle'])?> · <?=(int)$p['duration_days']?> days</small><p><?=sk1300_h($p['description'])?></p><?php if((int)($current['id']??0)===(int)$p['id']):?><b>✓ Current package</b><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1300_h(csrf_token())?>"><input type="hidden" name="package_id" value="<?=(int)$p['id']?>"><textarea name="note" rows="2" placeholder="Payment reference / note (optional)"></textarea><button class="btn">Request / Purchase</button></form><?php endif;?></article><?php endforeach;?></section><section class="history"><h2>Recent package requests</h2><table><tr><th>Package</th><th>Status</th><th>Payment</th><th>Date</th></tr><?php foreach($pending as $r):?><tr><td><?=sk1300_h($r['package_name'])?></td><td><?=sk1300_h($r['status'])?></td><td><?=sk1300_h($r['payment_status'])?></td><td><?=sk1300_h($r['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>
